void SessionIDType_template::log_match(const SessionIDType& match_value, boolean legacy) const
{
if(TTCN_Logger::VERBOSITY_COMPACT == TTCN_Logger::get_matching_verbosity()){
if(match(match_value, legacy)){
TTCN_Logger::print_logmatch_buffer();
TTCN_Logger::log_event_str(" matched");
} else{
if (template_selection == SPECIFIC_VALUE) {
size_t previous_size = TTCN_Logger::get_logmatch_buffer_len();
if (match_value.content().ispresent()){
if(!single_value->field_content.match(match_value.content(), legacy)){
TTCN_Logger::log_logmatch_info(".content");
single_value->field_content.log_match(match_value.content(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
} else {
if (!single_value->field_content.match_omit(legacy)){
 TTCN_Logger::log_logmatch_info(".content := omit with ");
TTCN_Logger::print_logmatch_buffer();
single_value->field_content.log();
TTCN_Logger::log_event_str(" unmatched");
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
}
}else {
TTCN_Logger::print_logmatch_buffer();
match_value.log();
TTCN_Logger::log_event_str(" with ");
log();
TTCN_Logger::log_event_str(" unmatched");
}
}
return;
}
if (template_selection == SPECIFIC_VALUE) {
TTCN_Logger::log_event_str("{ content := ");
if (match_value.content().ispresent()) single_value->field_content.log_match(match_value.content(), legacy);
else {
TTCN_Logger::log_event_str("omit with ");
single_value->field_content.log();
if (single_value->field_content.match_omit(legacy)) TTCN_Logger::log_event_str(" matched");
else TTCN_Logger::log_event_str(" unmatched");
}
TTCN_Logger::log_event_str(" }");
} else {
match_value.log();
TTCN_Logger::log_event_str(" with ");
log();
if (match(match_value, legacy)) TTCN_Logger::log_event_str(" matched");
else TTCN_Logger::log_event_str(" unmatched");
}
}

